class Bool:
  pass

class Enum:
  pass  # for adding enumeration types

class Record:
  def __init__(self, fields):
    self.fields = fields

  def __str__(self):
    return 'Record(fields = [' + ', '.join(str(f) for f in self.fields) + '])'

class Array:
  def __init__(self, base, lower, length):
    self.base, self.lower, self.length = base, lower, length

  def __str__(self):
    return (
      'Array(lower = '
      + str(self.lower)
      + ', length = '
      + str(self.length)
      + ', base = '
      + str(self.base)
      + ')'
    )
